window.AUTH=window.AUTH||{};window.AUTH["24-820"]={"d":"24-820","id":"2025/24-820","n":"Rutherford v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Daniel Rutherford","date":"2025-08-08","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/369264/20250808153852666_opening%20merits%20brief%20-%20Rutherford%20v.%20U.S.%20-%20No.%2024-820.pdf","side":"pet","n":134},{"k":"petitioner","label":"Brief of petitioner Johnnie Markel Carter","date":"2025-08-08","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/369300/20250808184320866_No.%2024-860_Brief.pdf","side":"pet","n":47},{"k":"respondent","label":"Brief of respondent United States","date":"2025-09-25","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/377956/20250925182237138_24-820bsUnitedStates.pdf","side":"res","n":76},{"k":"reply","label":"Reply of petitioner Daniel Rutherford","date":"2025-10-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/380752/20251027164806568_merits%20reply%20brief%20-%20Rutherford%20v.%20U.S.%20-%20No.%2024-820.pdf","side":"pet","n":60},{"k":"reply","label":"Reply of petitioner Johnnie Markel Carter","date":"2025-10-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-820/380758/20251027172028724_24-860_Reply%20Brief.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us2r40_o7kq.pdf","tr":true,"items":[{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"sum":"The Court held that the Federal Bureau of Prisons' method of determining \"good behavior,\" which was based on the inmate's time in prison rather than the overall sentence, was constitutional.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"sum":"Section 406 of the Act does not authorize the imposition of a special parole term even though that sanction is included within the penalty provision of the target offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47-48"}},{"t":"case","label":"Board of Pardons v. Allen","cite":"482 U.S. 369","y":1987,"id":"1986/86-461","sc":1,"sum":"When scrutinized under the Greenholtz standards, the Montana statute clearly creates a liberty interest in parole release that is protected by the Due Process Clause of the Fourteenth Amendment. Although, as in Greenholtz, the release decision here is \"necessarily... subjective and predictive\" and the Board's discretion \"very broad,\" nevertheless, the Montana statute, like the Nebraska statute, uses mandatory …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Bourjaily v. United States","cite":"483 U.S. 171","y":1987,"id":"1986/85-6725","sc":1,"sum":"Preponderance of the evidence; and no. When the existence and membership of a conspiracy are disputed, the traditional standard applies: the party offering the statements under Rule 801(d)(2)(E) must prove these preliminary facts by a preponderance of the evidence.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Buck v. Davis","cite":"580 U.S. 100","y":2017,"id":"2016/15-8049","sc":1,"sum":"The Court held that the U.S. Court of Appeals for the Fifth Circuit applied an unduly burdensome standard of review on a Certificate of Appealability (COA) for a claim of ineffective assistance of counsel when it denied the COA for failing to demonstrate extraordinary circumstances.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Bullington v. Missouri","cite":"451 U.S. 430","y":1981,"id":"1980/79-6740","sc":1,"sum":"Because under Missouri law the sentencing proceeding at petitioner's first trial was like the trial on the question of guilt or innocence, the protection afforded by the Double Jeopardy Clause to one acquitted by a jury is available to him, with respect to the death penalty, at his retrial. The reasoning of Stroud v. United States, 251 U. S. 15, is not controlling.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Cagle v. Harris","cite":"349 F.2d 404","y":1965,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/349/404/","by":{"0":"26"}},{"t":"case","label":"Center for Auto Safety v. Chrysler Grp., LLC","cite":"809 F.3d 1092","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/809/1092/","op":1,"by":{"0":"19"}},{"t":"case","label":"Concepcion v. United States","cite":"597 U.S. 481","y":2022,"id":"2021/20-1650","sc":1,"op":11,"ar":2,"sum":"Section 404(b) of the First Step Act of 2018, 132 Stat. 5222, allows district courts to consider intervening changes of law or fact in exercising their discretion to reduce a sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"1, 10, 22-23, 25, 37-39, 47, 49","1":"23, 27,47–48","2":"36","3":"1, 3, 4, 7, 9, 12, 13, 15","4":"6–7, 9, 22"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"op":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"0":"6","2":"8"}},{"t":"case","label":"Dean v. United States","cite":"581 U.S. 62","y":2017,"id":"2016/15-9260","sc":1,"sum":"The Court determined that 18 U.S.C. §924(c) does not prevent a sentencing court from using its discretion to consider the other mandatory minimum sentences a defendant might be facing when calculating an overall appropriate sentence.","sumSrc":"Oyez","by":{"0":"21, 25, 37-38","1":"48","2":"36, 37","3":"7, 15, 19","4":"7"}},{"t":"case","label":"Deputy v. du Pont","cite":"308 U.S. 488","y":1940,"id":"scdb/1939-103","sc":1,"sum":"1. In calcuiafing net income for taxation a deduction from gross income is allowhble only if there is clear statutory provision therefor.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"op":1,"sum":"The Court held that federal sentencing guidelines are binding when a district court imposes a new sentence under a revised guideline range.","sumSrc":"Oyez","by":{"0":"22, 49","1":"21, 23, 28","2":"6, 19","3":"10, 12"}},{"t":"case","label":"District of Columbia v. Wesby","cite":"583 U.S. 48","y":2018,"id":"2017/15-1485","sc":1,"sum":"The Court decided that (1) officers had probable cause to arrest a number of partygoers for unlawful entry under D.C. law under the totality of the circumstances, and (2) that the officers were entitled to qualified immunity because their actions were not clearly unlawful at the time.","sumSrc":"Oyez","by":{"0":"33-34","1":"44","2":"48","3":"5"}},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"op":1,"ar":1,"sum":"The Court held that criminals who had committed drug crimes before the passage of the Fair Sentencing Act of 2010 but were sentenced after its passage were entitled to the sentencing provisions laid out in the Act.","sumSrc":"Oyez","by":{"0":"31-32","2":"22"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"39, 42","2":"43","3":"15"}},{"t":"case","label":"Esteras v. United States","cite":"145 S. Ct. 2031","y":2025,"id":"2024/23-7483","sc":1,"sum":"A district court considering whether to revoke a defendant’s term of supervised release may not consider 18 U. S. C. §3553(a)(2)(A), which covers retribution vis-à-vis the defendant’s underlying criminal offense.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 20, 24, 34","3":"1, 3, 6, 9, 10, 11, 9","4":"28"}},{"t":"case","label":"Florida v. Harris","cite":"568 U.S. 237","y":2013,"id":"2012/11-817","sc":1,"sum":"The Court found that police officers do not need to show evidence of a drug-detection dog's reliability to prove probable cause.","sumSrc":"Oyez","by":{"0":"17","3":"5"}},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"op":3,"sum":"The Supreme Court, in a 7-2 ruling, reversed the appellate court and held that, under Booker , federal courts have the authority to set any reasonable sentence as long as they explain their reasoning. The Court made clear that Booker had removed the Guidelines from their earlier status as the primary determinate of a defendant's punishment, reaffirming the Guidelines' advisory status.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Garner v. Jones","cite":"529 U.S. 244","y":2000,"id":"1999/99-137","sc":1,"op":1,"sum":"The Court held that the retroactive application of the Georgia provision permitting extension of intervals between parole considerations does not to necessarily violate the Ex Post Facto Clause.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Graham v. Florida","cite":"560 U.S. 48","y":2010,"id":"2009/08-7412","sc":1,"sum":"The Court found that a non-homicidal conviction leading to a life sentence without parole for a juvenile violates the Eighth Amendment.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Greenholtz v. Inmates of Nebraska Penal & Corr. Complex","cite":"442 U.S. 1","y":1979,"id":"1978/78-201","sc":1,"sum":"The Court held that, although there is no constitutional right to an inmate’s release from prison prior to the expiration of a valid sentence, the specific wording of the Nebraska statute created a constitutionally protected expectation of parole.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"36, 43","3":"19"}},{"t":"case","label":"Hertz v. Woodman","cite":"218 U.S. 205","y":1910,"id":"scdb/1909-175","sc":1,"sum":"Where, as in this case, the certificate sufficiently states both the question and the desire of the Circuit Court of Appeals for instructions so that it may make a proper decision, it conforms in substance to. the provisions of § 6 of the act of March 3, 1891, c. 517, 26 Stat. 826.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"45-46"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"sum":"The Court ruled unanimously that the Sixth Circuit's rules for exhaustion of administrative remedies were not required by the Prisoner Litigation Reform Act. The opinion by Chief Justice John Roberts held that prisoners bring civil rights lawsuits do not need to demonstrate that they have already exhausted all administrative remedies.","sumSrc":"Oyez","by":{"0":"47","3":"19, 22"}},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"sum":"The term “mistake” in Federal Rule of Civil Procedure 60(b)(1) includes a judge’s errors of law; because Kemp’s motion alleged such an error, it was cognizable under Rule 60(b)(1) and untimely under Rule 60(c)’s 1-year limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17, 28"}},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"op":3,"ar":1,"sum":"Justice Ruth Bader Ginsburg authored the Court's 7-2 majority opinion reversing the Fourth Circuit and affirming the sentence handed down by the trial judge. Ginsburg noted that the drug trafficking statute still had some minimum sentencing requirements, and expressed the Court's confidence that district courts could maintain reasonably uniform approaches to cocaine sentencing.","sumSrc":"Oyez","by":{"0":"3, 36","1":"3, 37, 47–48","3":"6, 7","4":"7"}},{"t":"case","label":"Koon v. United States","cite":"518 U.S. 81","y":1996,"id":"1995/94-1664","sc":1,"op":1,"sum":"The Court held that the Court of Appeals should not review de novo a decision to depart from the Guideline sentencing range, but instead should ask whether the sentencing court abused its discretion.","sumSrc":"Oyez","by":{"0":"31-32, 35-36","1":"15, 39","3":"13, 19","4":"28"}},{"t":"case","label":"Kugler v. Helfant","cite":"421 U.S. 117","y":1975,"id":"1974/74-80","sc":1,"op":1,"sum":"One Helfant, who was a Municipal Court judge and a member of the New Jersey bar, brought this action in District Court permanently to enjoin the State Attorney General and other officials from proceeding with the prosecution of an indictment of Helfant, which had grown out of grand jury testimony that he had given as a result of assertedly collusive coercion by a State Deputy Attorney General and members of the New …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 48","1":"25","3":"4"}},{"t":"case","label":"Liljeberg v. Health Servs. Acquisition Corp.","cite":"486 U.S. 847","y":1988,"id":"1987/86-957","sc":1,"sum":"In 1977, pursuant to a plan to construct and operate a hospital in Kenner, Louisiana, petitioner formed a corporation (St. Jude) to apply for the necessary state \"certificate of need.\" During the next two years petitioner negotiated with Loyola University over a proposal to purchase as the hospital site a portion of Loyola's Kenner land for several million dollars, coupled with a plan to rezone Loyola's adjoining …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Metropolitan Stevedore Co. v. Rambo","cite":"515 U.S. 291","y":1995,"id":"1994/94-820","sc":1,"sum":"The Court held that a disability award may be modified under the LHWCA where there is a change in the employee's wage-earning capacity, even without any change in the employee's physical condition.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"op":2,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"0":"3","1":"3–4, 13–14, 27, 30, 33–34","2":"5, 45, 46","4":"25–26"}},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"572 U.S. 545","y":2014,"id":"2013/12-1184","sc":1,"op":1,"sum":"A case in which the Court defined \"exceptional\" cases as ones that simply stand out from others due to a frivolous nature related to its legal claims.","sumSrc":"Oyez","by":{"0":"16-17, 34, 48","3":"4"}},{"t":"case","label":"Ohio v. Robinette","cite":"519 U.S. 33","y":1996,"id":"1996/95-891","sc":1,"sum":"After establishing its federal jurisdiction, despite a claim that the matter involved aspects of Ohio's Constitution, the Court held that when looking at the totality of the circumstances it may be reasonably concluded that if a defendant consents to be searched, even if not first advised that he is \"free to go,\" the ensuing search will be recognized as voluntary.","sumSrc":"Oyez","by":{"0":"17","3":"4"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"sum":"The Court held that when a defendant's sentence has been set aside on appeal, a district court may consider evidence of the defendant's rehabilitation after the initial sentences, which may support lesser sentencing guidelines.","sumSrc":"Oyez","by":{"0":"23, 34","1":"28","3":"1, 3, 5, 8, 19","4":"25"}},{"t":"case","label":"Posadas v. National City Bank of New York","cite":"296 U.S. 497","y":1936,"id":"scdb/1935-071","sc":1,"by":{"0":"40"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Public Emps. Ret. Sys. of Ohio v. Betts","cite":"492 U.S. 158","y":1989,"id":"1988/88-389","sc":1,"op":1,"sum":"Section 4(f)(2) exempts all provisions of bona fide employee benefit plans from the purview of the ADEA, unless the plan is a subterfuge for discrimination in the non-fringe-benefit aspects of the employment relationship, and summary judgment for appellee was therefore inappropriate.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"sum":"Venue in a suit against a national banking association charged with violating the Securities Exchange Act of 1934 held to be governed by the venue provision of the National Bank Act, 12 U. S. C. § 94, which provides that an action against a national banking association may be had in any federal district court within the district in which such association may be established, rather than by § 27 of the Securities …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 39, 47","2":"36, 37","3":"15, 19"}},{"t":"case","label":"Sampson v. Murray","cite":"415 U.S. 61","y":1974,"id":"1973/72-403","sc":1,"sum":"Upon being notified that she was' going to be discharged on a specific date from her position as aprobationary Government employee, respondent filed this action claiming that the applicable Civil Service regulations for discharge of probationary employees had not been followed, and seeking a temporary injunction against her dismissal pending an administrative appeal to the Civil Service Commission (CSC). The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 48"}},{"t":"case","label":"Setser v. United States","cite":"566 U.S. 231","y":2012,"id":"2011/10-7387","sc":1,"op":2,"sum":"The Court held that a federal judge has discretion to order a federal sentence to run consecutively or concurrently with an anticipated state sentence.","sumSrc":"Oyez","by":{"0":"28","2":"39","3":"13, 14"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"State v. Reeder","cite":"60 S.E. 434","y":1908,"court":"S.C.","url":"https://www.courtlistener.com/c/S.E./60/434/","by":{"0":"25"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. U.S. ex rel. Rigsby","cite":"580 U.S. 264","y":2016,"id":"2016/15-513","sc":1,"sum":"The Court determined that a violation of the False Claims Act’s seal requirement does not mandate dismissal of the complaint.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Sure-Tan, Inc. v. NLRB","cite":"467 U.S. 883","y":1984,"id":"1983/82-945","sc":1,"sum":"The Court held that that the NLRB can act to protect the labor rights of illegal immigrants because it serves the broader purpose of labor to have all workers represented, regardless of immigration status. Precedent establishes that the Board can protect the rights of any employee. The petitioners’ actions illegally discouraged union activity and caused the deportation of their employees.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"sum":"The Court held that a district court may not give a defendant a longer prison sentence based on speculation about if and when the defendant would be able to participate in an inmate drug rehabilitation program.","sumSrc":"Oyez","by":{"0":"27","2":"5, 6, 37"}},{"t":"case","label":"United States v. Andrews","cite":"12 F.4th 255","y":2021,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/12/255/","op":4,"by":{"0":"5, 9-10, 42, 48","1":"6, 11","2":"9, 12"}},{"t":"case","label":"United States v. Angelos","cite":"345 F. Supp. 2d 1227","y":2004,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/345/1227/","by":{"0":"18-19"}},{"t":"case","label":"United States v. Arvizu","cite":"534 U.S. 266","y":2002,"id":"2001/00-1519","sc":1,"sum":"The Court held that the Court of Appeals' methodology was contrary to its prior decisions and that it reached the wrong result in this case.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"United States v. Bradley","cite":"97 F.4th 1214","y":2024,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/97/1214/","by":{"0":"31"}},{"t":"case","label":"United States v. Brooker","cite":"976 F.3d 228","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/976/228/","by":{"0":"4","1":"41, 45","4":"14"}},{"t":"case","label":"United States v. Chen","cite":"48 F.4th 1092","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/48/1092/","op":2,"by":{"0":"38-39, 41, 43","3":"8"}},{"t":"case","label":"United States v. Davis","cite":"961 F.3d 181","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/961/181/","by":{"0":"41"}},{"t":"case","label":"United States v. Diaco","cite":"457 F. Supp. 371","y":1978,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./457/371/","op":2,"ar":1,"by":{"0":"28","3":"13, 20, 21","4":"19–20"}},{"t":"case","label":"United States v. Dominguez","cite":"296 F.3d 192","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/296/192/","by":{"0":"16","1":"44"}},{"t":"case","label":"United States v. Fior D’Italia, Inc.","cite":"536 U.S. 238","y":2002,"id":"2001/01-463","sc":1,"sum":"The Court held that the law authorizes the IRS to use the aggregate estimation method. The Court reasoned that the law, by granting the IRS assessment authority, necessarily granted it the power to decide how to make that assessment within certain limits.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"United States v. Goodwin","cite":"486 F.3d 449","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/486/449/","by":{"0":"18"}},{"t":"case","label":"United States v. Hinton","cite":"2022 WL 988372","y":2022,"court":"E.D. Va. Mar. 31","by":{"0":"19"}},{"t":"case","label":"United States v. Honken","cite":"184 F.3d 961","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/184/961/","by":{"0":"16"}},{"t":"case","label":"United States v. Hungerford","cite":"465 F.3d 1113","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/1113/","by":{"0":"19"}},{"t":"case","label":"United States v. Hunter","cite":"770 F.3d 740","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/770/740/","by":{"0":"19"}},{"t":"case","label":"United States v. Hunter","cite":"12 F.4th 555","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/12/555/","op":3,"by":{"0":"48"}},{"t":"case","label":"United States v. Jarvis","cite":"999 F.3d 442","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/999/442/","op":2,"by":{"0":"43","2":"47","3":"6"}},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"sum":"The Court held that the length of a supervised release term cannot be reduced by reason of excess time served in prison.","sumSrc":"Oyez","by":{"0":"21","1":"49"}},{"t":"case","label":"United States v. Maumau","cite":"993 F.3d 821","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/993/821/","by":{"0":"31"}},{"t":"case","label":"United States v. McCall","cite":"56 F.4th 1048","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/56/1048/","by":{"0":"43-44, 47-48","2":"24"}},{"t":"case","label":"United States v. McKinnie","cite":"24 F.4th 583","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/24/583/","by":{"0":"48"}},{"t":"case","label":"United States v. Moody","cite":"115 F.4th 304","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/115/304/","by":{"0":"31"}},{"t":"case","label":"United States v. Myers","cite":"2021 WL 2401237","y":2021,"court":"D. Md. June 11","by":{"0":"19"}},{"t":"case","label":"United States v. Reisinger","cite":"128 U.S. 398","y":1888,"id":"scdb/1888-043","sc":1,"sum":".Section 13 of the Revised Statutes, which enacts that “the repeal of any statute.shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the repealing.- act shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"United States v. Rivera-Ruperto","cite":"852 F.3d 1","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/852/1/","by":{"0":"19"}},{"t":"case","label":"United States v. Rodriguez","cite":"451 F. Supp. 3d 392","y":2020,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/451/392/","by":{"0":"48"}},{"t":"case","label":"United States v. Rodriguez","cite":"2024 WL 5119901","y":2024,"court":"D.N.M. Dec. 16","by":{"0":"19"}},{"t":"case","label":"United States v. Rutherford","cite":"236 F. App’x 835","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/236/835/","by":{"0":"8, 18-19"}},{"t":"case","label":"United States v. Ruvalcaba","cite":"26 F.4th 14","y":2022,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/26/14/","op":2,"by":{"0":"24, 41-43"}},{"t":"case","label":"United States v. Smith","cite":"756 F.3d 1179","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1179/","by":{"0":"20, 24, 37","3":"20"}},{"t":"case","label":"United States v. Tucker","cite":"404 U.S. 443","y":1972,"id":"1971/70-86","sc":1,"sum":"Under these circumstances the Court of Appeals was correct in remanding the case to the District Court for reconsideration of the sentence imposed upon the defendant. Pp. 446-449. 431 F. 2d 1292, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","3":"8"}},{"t":"case","label":"United States v. Vaughn","cite":"62 F.4th 1071","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/62/1071/","sum":"Rejecting similar “divideand-conquer” approach under § 3582(c)(1)(A)(i).","sumSrc":"brief:0","by":{"0":"20, 30, 33-34","1":"44","2":"48"}},{"t":"case","label":"United States v. Washington","cite":"301 F. Supp. 2d 1306","y":2004,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/301/1306/","by":{"0":"18"}},{"t":"case","label":"United States v. Watts","cite":"519 U.S. 148","y":1997,"id":"1996/95-1906","sc":1,"sum":"In a 7-2 per curiam opinion, the Court held that a jury's verdict of acquittal does not prevent a sentencing court from considering a defendant's conduct underlying the acquitted charge, so long as that conduct has been proved by a preponderance of the evidence. Justices Antonin Scalia and Stephen G. Breyer concurred.","sumSrc":"Oyez","by":{"0":"23","3":"3"}},{"t":"case","label":"United States v. Wills","cite":"997 F.3d 685","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/685/","by":{"0":"32"}},{"t":"case","label":"Viterbo v. Friedlander","cite":"120 U.S. 707","y":1887,"id":"scdb/1886-177","sc":1,"sum":"The' Civil Code of Louisiana, following the civil law of Rome, Spain, and' France, and differing from the common law, regards a lease for years as a mere transfer of the thing leased; and holds the landlord bound, without any express’ covenant, to keep it in repair and otherwise fit for the use..for which it is leased, even When the want of repair or the unfitness is caused by an inevitable accident; and if he does …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Warden v. Marrero","cite":"417 U.S. 653","y":1974,"id":"1973/73-831","sc":1,"sum":"The Comprehensive Drug Abuse Prevention and Control Act of 1970, which became effective May 1, 1971, makes parole under the general parole statute, 18 U. S. C. § 4202, available for almost all narcotics offenders. Respondent, who had been sentenced before May 1, 1971, and was ineligible for parole under 26 U. S. C. § 7237 (d), which was repealed by the 1970 Act, sought habeas corpus in the District Court, claiming …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Welch v. Helvering","cite":"290 U.S. 111","y":1933,"id":"scdb/1933-003","sc":1,"op":1,"sum":"Describing line between “ordinary” and “extraordinary”.","sumSrc":"brief:0","by":{"0":"15, 17, 34, 48"}},{"t":"case","label":"Wilkinson v. Garland","cite":"601 U.S. 209","y":2024,"id":"2023/22-666","sc":1,"sum":"The Immigration Judge’s discretionary decision that Mr. Wilkinson failed to satisfy 8 U. S. C. §1229b(b)(1)(D)’s “exceptional and extremely unusual” hardship standard for determining eligibility for cancellation of removal is a mixed question of law and fact, reviewable under §1252(a)(2)(D)’s jurisdiction restoring exception for “questions of law”; the Third Circuit’s holding that the IJ’s decision was unreviewable under §1252(a)(2)(B)(i) was in error.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17, 48"}},{"t":"case","label":"Williams v. New York","cite":"337 U.S. 241","y":1949,"id":"scdb/1948-087","sc":1,"sum":"The Due Process Clause of the Fourteenth Amendment does not require that a person convicted after a fair trial be confronted with and permitted to cross-examine witnesses as to his prior criminal record considered by the judge in accordance with a state statute in determining what sentence to impose pursuant to broad discretion vested in him under state law-even when the jury recommends life imprisonment and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","3":"3"}},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"585 U.S. 274","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"14","2":"20"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"0":"39"}},{"t":"usc","label":"9 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/9/1","stext":{"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","paras":[[0,"\"Maritime transactions\", as herein defined, means charter parties, bills of lading of water carriers, agreements relating to wharfage, supplies furnished vessels or repairs to vessels, collisions, or any other matters in foreign commerce which, if the subject of controversy, would be embraced within admiralty jurisdiction; \"commerce\", as herein defined, means commerce among the several States or with foreign nations, or in any Territory of the United States or in the District of Columbia, or between any such Territory and another, or between any such Territory and any State or foreign nation, or between the District of Columbia and any State or Territory or foreign nation, but nothing herein contained shall apply to contracts of employment of seamen, railroad employees, or any other class of workers engaged in foreign or interstate commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/1?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","tname":"Arbitration","by":{"0":"39"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"1-2, 5-6, 8-11, 13, 32, 34, 36, 38, 41-42, 44","1":"43, 48, 51","2":"7","3":"1, 2, 4, 12, 14, 15, 23","4":"2, 4–6, 11"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","subs":["(a)"],"stext":{"head":"§1951. Interference with commerce by threats or violence","paras":[[0,"(a) Whoever in any way or degree obstructs, delays, or affects commerce or the movement of any article or commodity in commerce, by robbery or extortion or attempts or conspires so to do, or commits or threatens physical violence to any person or property in furtherance of a plan or purpose to do anything in violation of this section shall be fined under this title or imprisoned not more than twenty years, or both."],[0,"(b) As used in this section—"],[1,"(1) The term \"robbery\" means the unlawful taking or obtaining of personal property from the person or in the presence of another, against his will, by means of actual or threatened force, or violence, or fear of injury, immediate or future, to his person or property, or property in his custody or possession, or the person or property of a relative or member of his family or of anyone in his company at the time of the taking or obtaining."],[1,"(2) The term \"extortion\" means the obtaining of property from another, with his consent, induced by wrongful use of actual or threatened force, violence, or fear, or under color of official right."],[1,"(3) The term \"commerce\" means commerce within the District of Columbia, or any Territory or Possession of the United States; all commerce between any point in a State, Territory, Possession, or the District of Columbia and any point outside thereof; all commerce between points within the same State through any place outside such State; and all other commerce over which the United States has jurisdiction."],[0,"(c) This section shall not be construed to repeal, modify or affect section 17 of Title 15, sections 52, 101–115, 151–166 of Title 29 or sections 151–188 of Title 45."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1951?type=usc&year=mostrecent&link-type=html"},"head":"§1951. Interference with commerce by threats or violence","tname":"Crimes and Criminal Procedure","by":{"0":"7, 7","2":"11, 11"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1837","by":{"0":"3, 12, 14, 20-21, 23, 26-29, 46","1":"1, 3, 6, 14, 30, 35, 41","3":"1, 2, 3, 7, 8, 10, 12, 13, 21"}},{"t":"usc","label":"1 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/1/109","stext":{"head":"§109. Repeal of statutes as affecting existing liabilities","paras":[[0,"The repeal of any statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the repealing Act shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability. The expiration of a temporary statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the temporary statute shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/109?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§109. Repeal of statutes as affecting existing liabilities","tname":"General Provisions","by":{"0":"13, 45-46","2":"2, 18, 22"}},{"t":"usc","label":"16 U.S.C. § 472a","url":"https://www.law.cornell.edu/uscode/text/16/472a","subs":["(d)"],"by":{"0":"23"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)","(c)(1)","(c)(1)(A)(ii)","(c)(1)(C)","(c)(1)(D)(ii)","(c)(2000)","(c)(2006)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"5-10, 18-19, 24, 30, 36-37, 8, 8, 36, 8","2":"11, 13, 2-5, 8, 11-15, 18, 19, 21-24, 34, 44, 47-49, 8","3":"7, 16, 19","4":"2, 4–5, 10"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(3)","(a)(4)","(a)(6)","(a)(1)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"9, 12, 23-24, 31, 37, 43, 24, 24, 24","1":"4, 11, 30, 33","2":"19, 36, 37","3":"10, 11, 12, 10, 10, 10"}},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","subs":["(e)"],"by":{"0":"40"}},{"t":"usc","label":"18 U.S.C. § 3564","url":"https://www.law.cornell.edu/uscode/text/18/3564","subs":["(c)"],"by":{"0":"40"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)","(b)","(c)","(c)(1)(A)","(c)(1)(A)(i)","(c)(2)","(d)","(d)(2)(A)","(d)(2)(B)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§3582. Imposition of a sentence of imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"21, 39-40, 44, 46, 46, 2, 4, 22-23, 40, 1, 3-4, 9, 14, 34, 38-40, 42, 44, 22","2":"25, 6, 6, 6, 6, 6, 6, 6","3":"10, 10, 11, 14, 16, 21, 10"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(c)","(d)","(e)"],"by":{"0":"40, 40, 24"}},{"t":"usc","label":"18 U.S.C. § 3661","url":"https://www.law.cornell.edu/uscode/text/18/3661","stext":{"head":"§3661. Use of information for sentencing","paras":[[0,"No limitation shall be placed on the information concerning the background, character, and conduct of a person convicted of an offense which a court of the United States may receive and consider for the purpose of imposing an appropriate sentence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3661?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§3661. Use of information for sentencing","tname":"Crimes and Criminal Procedure","by":{"0":"12, 23","3":"2, 3, 8, 9, 10, 14, 15"}},{"t":"usc","label":"18 U.S.C. § 4205","url":"https://www.law.cornell.edu/uscode/text/18/4205","subs":["(g)(1976)","(a)(1982)","(b)(1982)","(g)(1982)"],"op":2,"tname":"Crimes and Criminal Procedure","by":{"0":"28","2":"29, 30, 29, 30, 29, 30","3":"13, 20"}},{"t":"usc","label":"19 U.S.C. § 1671c","url":"https://www.law.cornell.edu/uscode/text/19/1671c","subs":["(c)(4)(A)"],"by":{"0":"22","3":"7"}},{"t":"usc","label":"19 U.S.C. § 1673c","url":"https://www.law.cornell.edu/uscode/text/19/1673c","subs":["(c)(2)(A)"],"by":{"0":"22"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(a)(1)","(d)","(p)","(t)","(a)","(a)(2)(C)","(a)(2)"],"stext":{"head":"§994. Duties of the Commission","paras":[[0,"(a) The Commission, by affirmative vote of at least four members of the Commission, and pursuant to its rules and regulations and consistent with all pertinent provisions of any Federal statute shall promulgate and distribute to all courts of the United States and to the United States Probation System—"],[1,"(1) guidelines, as described in this section, for use of a sentencing court in determining the sentence to be imposed in a criminal case, including—"],[2,"(A) a determination whether to impose a sentence to probation, a fine, or a term of imprisonment;"],[2,"(B) a determination as to the appropriate amount of a fine or the appropriate length of a term of probation or a term of imprisonment;"],[2,"(C) a determination whether a sentence to a term of imprisonment should include a requirement that the defendant be placed on a term of supervised release after imprisonment, and, if so, the appropriate length of such a term;"],[2,"(D) a determination whether multiple sentences to terms of imprisonment should be ordered to run concurrently or consecutively; and"],[2,"(E) a determination under paragraphs (6) and (11) 1 of section 3563(b) of title 18;"],[1,"(2) general policy statements regarding application of the guidelines or any other aspect of sentencing or sentence implementation that in the view of the Commission would further the purposes set forth in section 3553(a)(2) of title 18, United States Code, including the appropriate use of—"],[2,"(A) the sanctions set forth in sections 3554, 3555, and 3556 of title 18;"],[2,"(B) the conditions of probation and supervised release set forth in sections 3563(b) and 3583(d) of title 18;"],[2,"(C) the sentence modification provisions set forth in sections 3563(c), 3564, 3573, and 3582(c) of title 18;"],[2,"(D) the fine imposition provisions set forth in section 3572 of title 18;"],[2,"(E) the authority granted under rule 11(e)(2) of the Federal Rules of Criminal Procedure to accept or reject a plea agreement entered into pursuant to rule 11(e)(1); and"],[2,"(F) the temporary release provisions set forth in section 3622 of title 18, and the prerelease custody provisions set forth in section 3624(c) of title 18; and"],[1,"(3) guidelines or general policy statements regarding the appropriate use of the provisions for revocation of probation set forth in section 3565 of title 18, and the provisions for modification of the term or conditions of supervised release and revocation of supervised release set forth in section 3583(e) of title 18."],[0,"(b)(1) The Commission, in the guidelines promulgated pursuant to subsection (a)(1), shall, for each category of offense involving each category of defendant, establish a sentencing range that is consistent with all pertinent provisions of title 18, United States Code."],[0,"(2) If a sentence specified by the guidelines includes a term of imprisonment, the maximum of the range established for such a term shall not exceed the minimum of that range by more than the greater of 25 percent or 6 months, except that, if the minimum term of the range is 30 years or more, the maximum may be life imprisonment."],[0,"(c) The Commission, in establishing categories of offenses for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) the grade of the offense;"],[1,"(2) the circumstances under which the offense was committed which mitigate or aggravate the seriousness of the offense;"],[1,"(3) the nature and degree of the harm caused by the offense, including whether it involved property, irreplaceable property, a person, a number of persons, or a breach of public trust;"],[1,"(4) the community view of the gravity of the offense;"],[1,"(5) the public concern generated by the offense;"],[1,"(6) the deterrent effect a particular sentence may have on the commission of the offense by others; and"],[1,"(7) the current incidence of the offense in the community and in the Nation as a whole."],[0,"(d) The Commission in establishing categories of defendants for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, with respect to a defendant, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) age;"],[1,"(2) education;"],[1,"(3) vocational skills;"],[1,"(4) mental and emotional condition to the extent that such condition mitigates the defendant's culpability or to the extent that such condition is otherwise plainly relevant;"],[1,"(5) physical condition, including drug dependence;"],[1,"(6) previous employment record;"],[1,"(7) family ties and responsibilities;"],[1,"(8) community ties;"],[1,"(9) role in the offense;"],[1,"(10) criminal history; and"],[1,"(11) degree of dependence upon criminal activity for a livelihood."],[0,"The Commission shall assure that the guidelines and policy statements are entirely neutral as to the race, sex, national origin, creed, and socioeconomic status of offenders."],[0,"(e) The Commission shall assure that the guidelines and policy statements, in recommending a term of imprisonment or length of a term of imprisonment, reflect the general inappropriateness of considering the education, vocational skills, employment record, family ties and responsibilities, and community ties of the defendant."],[0,"(f) The Commission, in promulgating guidelines pursuant to subsection (a)(1), shall promote the purposes set forth in section 991(b)(1), with particular attention to the requirements of subsection 991(b)(1)(B) for providing certainty and fairness in sentencing and reducing unwarranted sentence disparities."],[0,"(g) The Commission, in promulgating guidelines pursuant to subsection (a)(1) to meet the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code, shall take into account the nature and capacity of the penal, correctional, and other facilities and services available, and shall make recommendations concerning any change or expansion in the nature or capacity of such facilities and services that might become necessary as a result of the guidelines promulgated pursuant to the provisions of this chapter. The sentencing guidelines prescribed under this chapter shall be formulated to minimize the likelihood that the Federal prison population will exceed the capacity of the Federal prisons, as determined by the Commission."],[0,"(h) The Commission shall assure that the guidelines specify a sentence to a term of imprisonment at or near the maximum term authorized for categories of defendants in which the defendant is eighteen years old or older and—"],[1,"(1) has been convicted of a felony that is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46; and"],[1,"(2) has previously been convicted of two or more prior felonies, each of which is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46."],[0,"(i) The Commission shall assure that the guidelines specify a sentence to a substantial term of imprisonment for categories of defendants in which the defendant—"],[1,"(1) has a history of two or more prior Federal, State, or local felony convictions for offenses committed on different occasions;"],[1,"(2) committed the offense as part of a pattern of criminal conduct from which the defendant derived a substantial portion of the defendant's income;"],[1,"(3) committed the offense in furtherance of a conspiracy with three or more persons engaging in a pattern of racketeering activity in which the defendant participated in a managerial or supervisory capacity;"],[1,"(4) committed a crime of violence that constitutes a felony while on release pending trial, sentence, or appeal from a Federal, State, or local felony for which he was ultimately convicted; or"],[1,"(5) committed a felony that is set forth in section 401 or 1010 of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 841 and 960), and that involved trafficking in a substantial quantity of a controlled substance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/994?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§994. Duties of the Commission","tname":"Judiciary and Judicial Procedure","by":{"0":"3, 21, 40, 7, 2, 4, 11, 20-22, 24, 27, 31, 35, 38-39","2":"43, 43, 3, 7, 17, 32, 34, 36, 42, 43, 47","3":"6, 7, 8, 9","4":"17, 24, 26–27"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"ar":2,"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"0":"44","2":"11, 18, 44, 4","3":"23"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(e)"],"stext":{"head":"§160. Prevention of unfair labor practices","paras":[[0,"(a) Powers of Board generally"],[0,"The Board is empowered, as hereinafter provided, to prevent any person from engaging in any unfair labor practice (listed in section 158 of this title) affecting commerce. This power shall not be affected by any other means of adjustment or prevention that has been or may be established by agreement, law, or otherwise: Provided, That the Board is empowered by agreement with any agency of any State or Territory to cede to such agency jurisdiction over any cases in any industry (other than mining, manufacturing, communications, and transportation except where predominantly local in character) even though such cases may involve labor disputes affecting commerce, unless the provision of the State or Territorial statute applicable to the determination of such cases by such agency is inconsistent with the corresponding provision of this subchapter or has received a construction inconsistent therewith."],[0,"(b) Complaint and notice of hearing; answer; court rules of evidence inapplicable"],[0,"Whenever it is charged that any person has engaged in or is engaging in any such unfair labor practice, the Board, or any agent or agency designated by the Board for such purposes, shall have power to issue and cause to be served upon such person a complaint stating the charges in that respect, and containing a notice of hearing before the Board or a member thereof, or before a designated agent or agency, at a place therein fixed, not less than five days after the serving of said complaint: Provided, That no complaint shall issue based upon any unfair labor practice occurring more than six months prior to the filing of the charge with the Board and the service of a copy thereof upon the person against whom such charge is made, unless the person aggrieved thereby was prevented from filing such charge by reason of service in the armed forces, in which event the six-month period shall be computed from the day of his discharge. Any such complaint may be amended by the member, agent, or agency conducting the hearing or the Board in its discretion at any time prior to the issuance of an order based thereon. The person so complained of shall have the right to file an answer to the original or amended complaint and to appear in person or otherwise and give testimony at the place and time fixed in the complaint. In the discretion of the member, agent, or agency conducting the hearing or the Board, any other person may be allowed to intervene in the said proceeding and to present testimony. Any such proceeding shall, so far as practicable, be conducted in accordance with the rules of evidence applicable in the district courts of the United States under the rules of civil procedure for the district courts of the United States, adopted by the Supreme Court of the United States pursuant to section 2072 of title 28."],[0,"(c) Reduction of testimony to writing; findings and orders of Board"],[0,"The testimony taken by such member, agent, or agency or the Board shall be reduced to writing and filed with the Board. Thereafter, in its discretion, the Board upon notice may take further testimony or hear argument. If upon the preponderance of the testimony taken the Board shall be of the opinion that any person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue and cause to be served on such person an order requiring such person to cease and desist from such unfair labor practice, and to take such affirmative action including reinstatement of employees with or without back pay, as will effectuate the policies of this subchapter: Provided, That where an order directs reinstatement of an employee, back pay may be required of the employer or labor organization, as the case may be, responsible for the discrimination suffered by him: And provided further, That in determining whether a complaint shall issue alleging a violation of subsection (a)(1) or (a)(2) of section 158 of this title, and in deciding such cases, the same regulations and rules of decision shall apply irrespective of whether or not the labor organization affected is affiliated with a labor organization national or international in scope. Such order may further require such person to make reports from time to time showing the extent to which it has complied with the order. If upon the preponderance of the testimony taken the Board shall not be of the opinion that the person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue an order dismissing the said complaint. No order of the Board shall require the reinstatement of any individual as an employee who has been suspended or discharged, or the payment to him of any back pay, if such individual was suspended or discharged for cause. In case the evidence is presented before a member of the Board, or before an administrative law judge or judges thereof, such member, or such judge or judges as the case may be, shall issue and cause to be served on the parties to the proceeding a proposed report, together with a recommended order, which shall be filed with the Board, and if no exceptions are filed within twenty days after service thereof upon such parties, or within such further period as the Board may authorize, such recommended order shall become the order of the Board and become effective as therein prescribed."],[0,"(d) Modification of findings or orders prior to filing record in court"],[0,"Until the record in a case shall have been filed in a court, as hereinafter provided, the Board may at any time upon reasonable notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any finding or order made or issued by it."],[0,"(e) Petition to court for enforcement of order; proceedings; review of judgment"],[0,"The Board shall have power to petition any court of appeals of the United States, or if all the courts of appeals to which application may be made are in vacation, any district court of the United States, within any circuit or district, respectively, wherein the unfair labor practice in question occurred or wherein such person resides or transacts business, for the enforcement of such order and for appropriate temporary relief or restraining order, and shall file in the court the record in the proceedings, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall cause notice thereof to be served upon such person, and thereupon shall have jurisdiction of the proceeding and of the question determined therein, and shall have power to grant such temporary relief or restraining order as it deems just and proper, and to make and enter a decree enforcing, modifying and enforcing as so modified, or setting aside in whole or in part the order of the Board. No objection that has not been urged before the Board, its member, agent, or agency, shall be considered by the court, unless the failure or neglect to urge such objection shall be excused because of extraordinary circumstances. The findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive. If either party shall apply to the court for leave to adduce additional evidence and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the hearing before the Board, its member, agent, or agency, the court may order such additional evidence to be taken before the Board, its member, agent, or agency, and to be made a part of the record. The Board may modify its findings as to the facts, or make new findings by reason of additional evidence so taken and filed, and it shall file such modified or new findings, which findings with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive, and shall file its recommendations, if any, for the modification or setting aside of its original order. Upon the filing of the record with it the jurisdiction of the court shall be exclusive and its judgment and decree shall be final, except that the same shall be subject to review by the appropriate United States court of appeals if application was made to the district court as hereinabove provided, and by the Supreme Court of the United States upon writ of certiorari or certification as provided in section 1254 of title 28."],[0,"(f) Review of final order of Board on petition to court"],[0,"Any person aggrieved by a final order of the Board granting or denying in whole or in part the relief sought may obtain a review of such order in any United States court of appeals in the circuit wherein the unfair labor practice in question was alleged to have been engaged in or wherein such person resides or transacts business, or in the United States Court of Appeals for the District of Columbia, by filing in such a court a written petition praying that the order of the Board be modified or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Board, and thereupon the aggrieved party shall file in the court the record in the proceeding, certified by the Board, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall proceed in the same manner as in the case of an application by the Board under subsection (e), and shall have the same jurisdiction to grant to the Board such temporary relief or restraining order as it deems just and proper, and in like manner to make and enter a decree enforcing, modifying, and enforcing as so modified, or setting aside in whole or in part the order of the Board; the findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall in like manner be conclusive."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/160?type=usc&year=mostrecent&link-type=html"},"head":"§160. Prevention of unfair labor practices","tname":"Labor","by":{"0":"29","3":"13"}},{"t":"usc","label":"42 U.S.C. § 256","url":"https://www.law.cornell.edu/uscode/text/42/256","subs":["(c)"],"stext":{"head":"§256. Grants to strengthen the effectiveness, efficiency, and coordination of services for the uninsured and underinsured","paras":[[0,"(a) In general"],[0,"The Secretary may award grants to eligible entities to assist in the development of integrated health care delivery systems to serve communities of individuals who are uninsured and individuals who are underinsured—"],[1,"(1) to improve the efficiency of, and coordination among, the providers providing services through such systems;"],[1,"(2) to assist communities in developing programs targeted toward preventing and managing chronic diseases; and"],[1,"(3) to expand and enhance the services provided through such systems."],[0,"(b) Eligible entities"],[0,"To be eligible to receive a grant under this section, an entity shall be an entity that—"],[1,"(1) represents a consortium—"],[2,"(A) whose principal purpose is to provide a broad range of coordinated health care services for a community defined in the entity's grant application as described in paragraph (2); and"],[2,"(B) that includes at least one of each of the following providers that serve the community (unless such provider does not exist within the community, declines or refuses to participate, or places unreasonable conditions on their participation)—"],[3,"(i) a Federally qualified health center (as defined in section 1395x(aa) of this title);"],[3,"(ii) a hospital with a low-income utilization rate (as defined in section 1396r–4(b)(3) of this title), that is greater than 25 percent;"],[3,"(iii) a public health department; and"],[3,"(iv) an interested public or private sector health care provider or an organization that has traditionally served the medically uninsured and underserved; and"],[1,"(2) submits to the Secretary an application, in such form and manner as the Secretary shall prescribe, that—"],[2,"(A) defines a community or geographic area of uninsured and underinsured individuals;"],[2,"(B) identifies the providers who will participate in the consortium's program under the grant, and specifies each provider's contribution to the care of uninsured and underinsured individuals in the community, including the volume of care the provider provides to beneficiaries under the medicare, medicaid, and State child health insurance programs and to patients who pay privately for services;"],[2,"(C) describes the activities that the applicant and the consortium propose to perform under the grant to further the objectives of this section;"],[2,"(D) demonstrates the consortium's ability to build on the current system (as of the date of submission of the application) for serving a community or geographic area of uninsured and underinsured individuals by involving providers who have traditionally provided a significant volume of care for that community;"],[2,"(E) demonstrates the consortium's ability to develop coordinated systems of care that either directly provide or ensure the prompt provision of a broad range of high-quality, accessible services, including, as appropriate, primary, secondary, and tertiary services, as well as substance abuse treatment and mental health services in a manner that assures continuity of care in the community or geographic area;"],[2,"(F) provides evidence of community involvement in the development, implementation, and direction of the program that the entity proposes to operate;"],[2,"(G) demonstrates the consortium's ability to ensure that individuals participating in the program are enrolled in public insurance programs for which the individuals are eligible or know of private insurance programs where available;"],[2,"(H) presents a plan for leveraging other sources of revenue, which may include State and local sources and private grant funds, and integrating current and proposed new funding sources in a way to assure long-term sustainability of the program;"],[2,"(I) describes a plan for evaluation of the activities carried out under the grant, including measurement of progress toward the goals and objectives of the program and the use of evaluation findings to improve program performance;"],[2,"(J) demonstrates fiscal responsibility through the use of appropriate accounting procedures and appropriate management systems;"],[2,"(K) demonstrates the consortium's commitment to serve the community without regard to the ability of an individual or family to pay by arranging for or providing free or reduced charge care for the poor; and"],[2,"(L) includes such other information as the Secretary may prescribe."],[0,"(c) Limitations"],[0,"(1) Number of awards"],[0,"(A) In general"],[2,"For each of fiscal years 2003, 2004, 2005, and 2006, the Secretary may not make more than 35 new awards under subsection (a) (excluding renewals of such awards)."],[0,"(B) Rule of construction"],[2,"This paragraph shall not be construed to affect awards made before fiscal year 2003."],[0,"(2) In general"],[1,"An eligible entity may not receive a grant under this section (including with respect to any such grant made before fiscal year 2003) for more than 3 consecutive fiscal years, except that such entity may receive such a grant award for not more than 1 additional fiscal year if—"],[2,"(A) the eligible entity submits to the Secretary a request for a grant for such an additional fiscal year;"],[2,"(B) the Secretary determines that extraordinary circumstances (as defined in paragraph (3)) justify the granting of such request; and"],[2,"(C) the Secretary determines that granting such request is necessary to further the objectives described in subsection (a)."],[0,"(3) Extraordinary circumstances"],[0,"(A) In general"],[2,"In paragraph (2), the term \"extraordinary circumstances\" means an event (or events) that is outside of the control of the eligible entity that has prevented the eligible entity from fulfilling the objectives described by such entity in the application submitted under subsection (b)(2)."],[0,"(B) Examples"],[2,"Extraordinary circumstances include—"],[3,"(i) natural disasters or other major disruptions to the security or health of the community or geographic area served by the eligible entity; or"],[3,"(ii) a significant economic deterioration in the community or geographic area served by such eligible entity, that directly and adversely affects the entity receiving an award under subsection (a)."],[0,"(d) Priorities"],[0,"In awarding grants under this section, the Secretary—"],[1,"(1) shall accord priority to applicants that demonstrate the extent of unmet need in the community involved for a more coordinated system of care; and"],[1,"(2) may accord priority to applicants that best promote the objectives of this section, taking into consideration the extent to which the application involved—"],[2,"(A) identifies a community whose geographical area has a high or increasing percentage of individuals who are uninsured;"],[2,"(B) demonstrates that the applicant has included in its consortium providers, support systems, and programs that have a tradition of serving uninsured individuals and underinsured individuals in the community;"],[2,"(C) shows evidence that the program would expand utilization of preventive and primary care services for uninsured and underinsured individuals and families in the community, including behavioral and mental health services, oral health services, or substance abuse services;"],[2,"(D) proposes a program that would improve coordination between health care providers and appropriate social service providers;"],[2,"(E) demonstrates collaboration with State and local governments;"],[2,"(F) demonstrates that the applicant makes use of non-Federal contributions to the greatest extent possible; or"],[2,"(G) demonstrates a likelihood that the proposed program will continue after support under this section ceases."],[0,"(e) Use of funds"],[0,"(1) Use by grantees"],[0,"(A) In general"],[2,"Except as provided in paragraphs (2) and (3), a grantee may use amounts provided under this section only for—"],[3,"(i) direct expenses associated with achieving the greater integration of a health care delivery system so that the system either directly provides or ensures the provision of a broad range of culturally competent services, as appropriate, including primary, secondary, and tertiary services, as well as substance abuse treatment and mental health services; and"],[3,"(ii) direct patient care and service expansions to fill identified or documented gaps within an integrated delivery system."],[0,"(B) Specific uses"],[2,"The following are examples of purposes for which a grantee may use grant funds under this section, when such use meets the conditions stated in subparagraph (A):"],[3,"(i) Increases in outreach activities and closing gaps in health care service."],[3,"(ii) Improvements to case management."],[3,"(iii) Improvements to coordination of transportation to health care facilities."],[3,"(iv) Development of provider networks and other innovative models to engage physicians in voluntary efforts to serve the medically underserved within a community."],[3,"(v) Recruitment, training, and compensation of necessary personnel."],[3,"(vi) Acquisition of technology for the purpose of coordinating care."],[3,"(vii) Improvements to provider communication, including implementation of shared information systems or shared clinical systems."],[3,"(viii) Development of common processes for determining eligibility for the programs provided through the system, including creating common identification cards and single sliding scale discounts."],[3,"(ix) Development of specific prevention and disease management tools and processes."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/256?type=usc&year=mostrecent&link-type=html"},"head":"§256. Grants to strengthen the effectiveness, efficiency, and coordination of services for the uninsured and underinsured","tname":"The Public Health and Welfare","by":{"0":"22","3":"7"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)(6)","(b)"],"by":{"0":"28","3":"13"}},{"t":"reg","label":"Notice, Sentencing Guidelines for United States Courts, 88 Fed. Reg. 28,254","url":"https://www.govinfo.gov/link/fr/88/28254","by":{"0":"6-7, 30","1":"8, 32, 42","2":"9"}},{"t":"case","label":"Batterton v. Francis","cite":"432 U.S. 416","y":1977,"id":"1976/75-1181","sc":1,"op":4,"sum":"The regulation is a proper exercise of the Secretary's statutory authority and is reasonable.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 19, 22, 40, 46","2":"32, 33, 42","4":"1, 11, 27"}},{"t":"case","label":"Braxton v. United States","cite":"500 U.S. 344","y":1991,"id":"1990/90-5358","sc":1,"sum":"The court below misapplied the § 1B1.2(a) proviso.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4, 8"}},{"t":"case","label":"Brogan v. United States","cite":"522 U.S. 398","y":1998,"id":"1997/96-1579","sc":1,"sum":"In a 7-to-2 decision, the Court held that the imposition of criminal liability for false statements is not limited only to those falsehoods that pervert governmental functions - it applies to statements \"of whatever kind.\" Moreover, even if the \"exculpatory no\" doctrine did apply to statements that do not impede federal functions, Brogan would not benefit from it since his falsehoods were intended to prevent federal agents from uncovering the truth.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"579 U.S. 261","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"FCC v. Consumers’ Rsch.","cite":"145 S. Ct. 2428","y":2025,"url":"https://www.courtlistener.com/c/S.%20Ct./145/2428/","sc":1,"sum":"Noting that pre-approval submission to Congress would satisfy a “stringent” form of nondelegation review.","sumSrc":"brief:1","by":{"1":"34–35"}},{"t":"case","label":"FCC v. Prometheus Radio Project","cite":"592 U.S. 414","y":2021,"id":"2020/19-1231","sc":1,"sum":"The Federal Communications Commission’s 2017 decision to repeal or modify three of its media ownership rules was not arbitrary or capricious for purposes of the Administrative Procedure Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32–33"}},{"t":"case","label":"Gundy v. United States","cite":"588 U.S. 128","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25, 34"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"591 U.S. 657","y":2020,"id":"2019/19-431","sc":1,"ar":1,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"1":"33, 47, 49–50","4":"7–8"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"op":6,"ar":2,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20, 25, 36","2":"32, 41"}},{"t":"case","label":"Pickens v. Hamilton-Ryker IT Sols., LLC","cite":"133 F.4th 575","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/133/575/","by":{"1":"21, 31, 33"}},{"t":"case","label":"Stinson v. United States","cite":"508 U.S. 36","y":1993,"id":"1992/91-8685","sc":1,"sum":"After petitioner Stinson pleaded guilty to a five-count indictment resulting from his robbery of a bank, the District Court sentenced him as a career offender under United States Sentencing Commission, Guidelines Manual §4B1.1, which requires, inter alia,that \"the instant offense of conviction [be] a crime of violence.\" The court found that Stinson's offense of possession of a firearm by a convicted felon, 18 U. S. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 21, 35"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"United States v. Dupree","cite":"57 F.4th 1269","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/57/1269/","by":{"1":"27–28"}},{"t":"case","label":"United States v. Galante","cite":"111 F.3d 1029","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/111/1029/","by":{"1":"26"}},{"t":"case","label":"United States v. Jackson","cite":"964 F.3d 197","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/964/197/","by":{"1":"50"}},{"t":"case","label":"United States v. LaBonte","cite":"520 U.S. 751","y":1997,"id":"1996/95-1726","sc":1,"sum":"The Court held that the Commission's interpretation was inconsistent with section 994(h)'s plain language, and therefore \"maximum term authorized\" must be read to include all applicable statutory sentencing enhancements. \"Congress surely did not establish enhanced penalties for repeat offenders only to have the Commission render them a virtual nullity,\" wrote Justice Thomas for the Court.","sumSrc":"Oyez","by":{"1":"4, 35, 37–38, 47","2":"43, 44","4":"26"}},{"t":"case","label":"United States v. McCoy","cite":"981 F.3d 271","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/981/271/","op":1,"by":{"1":"17, 51","2":"31"}},{"t":"case","label":"United States v. Rutherford","cite":"120 F.4th 360","y":2024,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/120/360/","op":4,"by":{"1":"50"}},{"t":"case","label":"United States v. Sprei","cite":"145 F.3d 528","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/145/528/","by":{"1":"44"}},{"t":"case","label":"United States v. Vargas","cite":"74 F.4th 673","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/74/673/","by":{"1":"28"}},{"t":"case","label":"United States v. Veliz","cite":"2024 WL 4475055","y":2024,"court":"S.D. Fla. Oct. 11","by":{"1":"42"}},{"t":"case","label":"Wayman v. Southard","cite":"10 Wheat. 1","y":1825,"url":"https://www.courtlistener.com/c/Wheat./10/1/","op":1,"by":{"1":"20, 24–25"}},{"t":"case","label":"White Stallion Energy Ctr., LLC v. EPA","cite":"748 F.3d 1222","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/748/1222/","by":{"1":"20"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’n","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","by":{"1":"39"}},{"t":"usc","label":"28 U.S.C. § 991","url":"https://www.law.cornell.edu/uscode/text/28/991","subs":["(b)","(b)(1)(B)"],"stext":{"head":"§991. United States Sentencing Commission; establishment and purposes","paras":[[0,"(a) There is established as an independent commission in the judicial branch of the United States a United States Sentencing Commission which shall consist of seven voting members and one nonvoting member. The President, after consultation with representatives of judges, prosecuting attorneys, defense attorneys, law enforcement officials, senior citizens, victims of crime, and others interested in the criminal justice process, shall appoint the voting members of the Commission, by and with the advice and consent of the Senate, one of whom shall be appointed, by and with the advice and consent of the Senate, as the Chair and three of whom shall be designated by the President as Vice Chairs. At least 3 of the members shall be Federal judges selected after considering a list of six judges recommended to the President by the Judicial Conference of the United States. Not more than four of the members of the Commission shall be members of the same political party, and of the three Vice Chairs, no more than two shall be members of the same political party. The Attorney General, or the Attorney General's designee, shall be an ex officio, nonvoting member of the Commission. The Chair, Vice Chairs, and members of the Commission shall be subject to removal from the Commission by the President only for neglect of duty or malfeasance in office or for other good cause shown."],[0,"(b) The purposes of the United States Sentencing Commission are to—"],[1,"(1) establish sentencing policies and practices for the Federal criminal justice system that—"],[2,"(A) assure the meeting of the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code;"],[2,"(B) provide certainty and fairness in meeting the purposes of sentencing, avoiding unwarranted sentencing disparities among defendants with similar records who have been found guilty of similar criminal conduct while maintaining sufficient flexibility to permit individualized sentences when warranted by mitigating or aggravating factors not taken into account in the establishment of general sentencing practices; and"],[2,"(C) reflect, to the extent practicable, advancement in knowledge of human behavior as it relates to the criminal justice process; and"],[1,"(2) develop means of measuring the degree to which the sentencing, penal, and correctional practices are effective in meeting the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/991?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§991. United States Sentencing Commission; establishment and purposes","tname":"Judiciary and Judicial Procedure","by":{"1":"4, 30, 33","2":"6, 34"}},{"t":"reg","label":"87 Fed. Reg. 60438","url":"https://www.govinfo.gov/link/fr/87/60438","by":{"1":"7"}},{"t":"reg","label":"88 Fed. Reg. 7180","url":"https://www.govinfo.gov/link/fr/88/7180","by":{"1":"32","4":"5"}},{"t":"case","label":"Br. for the United States in Opp’n, Jarvis v. United States","cite":"2021 WL 5864543","y":2021,"court":"U.S. Dec. 8","by":{"1":"7, 38","4":"4"}},{"t":"case","label":"Brown v. United States","cite":"2005 WL 1330726","y":2005,"court":"S.D. Ga. May 9","sum":"Rejecting reliance on nonretroactive postconviction decision of this Court as “extraordinary and compelling” reason.","sumSrc":"brief:2","by":{"2":"30"}},{"t":"case","label":"Brown v. United States","cite":"602 U.S. 101","y":2024,"id":"2023/22-6389","sc":1,"sum":"For purposes of the Armed Career Criminal Act’s 15-year mandatory minimum sentence on certain defendants with three or more previous convictions, a state drug conviction counts as an ACCA predicate if it involved a drug on the federal schedules at the time of that offense.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"38"}},{"t":"case","label":"Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"id":"2020/19-5807","sc":1,"sum":"The jury-unanimity rule announced in Ramos v. Louisiana, 590 U. S. ___, does not apply retroactively on federal collateral review.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"2, 18"}},{"t":"case","label":"Hewitt v. United States","cite":"145 S. Ct. 2165","y":2025,"id":"2024/23-1002","sc":1,"op":5,"ar":2,"sum":"Because a sentence “has . . . been imposed” for purposes of §403(b) of the First Step Act only if the sentence is extant (i.e., has not been vacated), the Act’s more lenient penalties apply to defendants whose previous 18 U. S. C. §924(c) sentences have been vacated and who need to be resentenced following the Act’s enactment; the judgment of the Fifth Circuit is reversed and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"3, 16, 18, 19, 21-24, 49","4":"5"}},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"sum":"The saving clause in 28 U. S. C. §2255(e) does not allow a prisoner asserting an intervening change in the interpretation of a criminal statute to circumvent the Antiterrorism and Effective Death Penalty Act of 1996’s restrictions on second or successive §2255 motions by filing a habeas petition under §2241.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"31"}},{"t":"case","label":"Koons v. United States","cite":"584 U.S. 700","y":2018,"id":"2017/17-5716","sc":1,"op":1,"sum":"The Court decided that the petitioners, who were criminal defendants, were not eligible for sentence reductions under 18 U.S.C. § 3582(c)(2) because their sentences were not “based on” their lowered Federal Sentencing Guidelines ranges, but rather were “based on” the mandatory minimum sentences for their offenses and their substantial assistance to the government.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Monsalvo v. Bondi","cite":"145 S. Ct. 1232","y":2025,"id":"2024/23-929","sc":1,"sum":"Under 8 U. S. C. §1229c(b)(2), a voluntary-departure deadline that falls on a weekend or legal holiday extends to the next business day.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"28"}},{"t":"case","label":"Neal v. United States","cite":"516 U.S. 284","y":1996,"id":"1995/94-9088","sc":1,"sum":"Authored by Justice Anthony Kennedy, the Court held that Section 841(b)(1) directs a sentencing court to take into account the actual weight of the blotter paper with its absorbed LSD, even though the U. S. Sentencing Commission's Guidelines Manual requires a different method of calculating the weight of an LSD mixture or substance.","sumSrc":"Oyez","by":{"2":"6, 44, 45"}},{"t":"case","label":"Perdue v. Kenny A. ex rel. Winn","cite":"559 U.S. 542","y":2010,"id":"2009/08-970","sc":1,"sum":"The Court held that reasonable attorneys' fees awarded under a federal fee-shifting statute can be enhanced based on the quality of the attorney's performance and results obtained in exceptional circumstances.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Quarles v. United States","cite":"587 U.S. 645","y":2019,"id":"2018/17-778","sc":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"26"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"592 U.S. 43","y":2020,"id":"2020/19-71","sc":1,"sum":"The Religious Freedom Restoration Act of 1993’s express remedies provision, see 42 U. S. C. §2000bb–1(c), permits litigants, when appropriate, to obtain money damages against federal officials in their individual capacities.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"42"}},{"t":"case","label":"Terry v. United States","cite":"593 U.S. 486","y":2021,"id":"2020/20-5904","sc":1,"sum":"A sentence reduction under the First Step Act is available only if an offender’s prior conviction of a crack cocaine offense triggered a mandatory minimum sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4, 44"}},{"t":"case","label":"United States v. Bricker","cite":"135 F.4th 427","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/135/427/","op":1,"by":{"2":"38"}},{"t":"case","label":"United States v. Crandall","cite":"25 F.4th 582","y":2022,"url":"https://www.courtlistener.com/c/F.4th/25/582/","op":1,"by":{"2":"20"}},{"t":"case","label":"United States v. Fulton","cite":"2024 WL 4503467","y":2024,"court":"E.D. La. Oct. 16","by":{"2":"45"}},{"t":"case","label":"United States v. Havener","cite":"905 F.2d 3","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/905/3/","by":{"2":"30"}},{"t":"case","label":"United States v. Howard","cite":"2024 WL 112010","y":2024,"court":"D. Md. Jan. 10","by":{"2":"48"}},{"t":"case","label":"United States v. Jenkins","cite":"50 F.4th 1185","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/50/1185/","op":1,"by":{"2":"24-27"}},{"t":"case","label":"United States v. Martin","cite":"2025 WL 1728694","y":2025,"court":"W.D. Va. June 20","by":{"2":"48"}},{"t":"case","label":"United States v. Smith","cite":"650 F.2d 206","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/650/206/","by":{"2":"25"}},{"t":"case","label":"United States v. Wesley","cite":"60 F.4th 1277","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/60/1277/","by":{"2":"27","3":"21"}},{"t":"law","label":"Pub. L. No. 105-386","url":"https://www.govinfo.gov/link/plaw/105/public/386","by":{"2":"8"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","subs":["(b)(1)"],"stext":{"head":"§3551. Authorized sentences","paras":[[0,"(a) In General.—Except as otherwise specifically provided, a defendant who has been found guilty of an offense described in any Federal statute, including sections 13 and 1153 of this title, other than an Act of Congress applicable exclusively in the District of Columbia or the Uniform Code of Military Justice, shall be sentenced in accordance with the provisions of this chapter so as to achieve the purposes set forth in subparagraphs (A) through (D) of section 3553(a)(2) to the extent that they are applicable in light of all the circumstances of the case."],[0,"(b) Individuals.—An individual found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B;"],[1,"(2) a fine as authorized by subchapter C; or"],[1,"(3) a term of imprisonment as authorized by subchapter D."],[0,"A sentence to pay a fine may be imposed in addition to any other sentence. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."],[0,"(c) Organizations.—An organization found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B; or"],[1,"(2) a fine as authorized by subchapter C."],[0,"A sentence to pay a fine may be imposed in addition to a sentence to probation. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3551?type=usc&year=mostrecent&link-type=html"},"head":"§3551. Authorized sentences","tname":"Crimes and Criminal Procedure","by":{"2":"6","3":"10"}},{"t":"usc","label":"18 U.S.C. § 4042","url":"https://www.law.cornell.edu/uscode/text/18/4042","subs":["(a)"],"stext":{"head":"§4042. Duties of Bureau of Prisons","paras":[[0,"(a) In General.—The Bureau of Prisons, under the direction of the Attorney General, shall—"],[1,"(1) have charge of the management and regulation of all Federal penal and correctional institutions;"],[1,"(2) provide suitable quarters and provide for the safekeeping, care, and subsistence of all persons charged with or convicted of offenses against the United States, or held as witnesses or otherwise;"],[1,"(3) provide for the protection, instruction, and discipline of all persons charged with or convicted of offenses against the United States;"],[1,"(4) provide technical assistance to State, tribal, and local governments in the improvement of their correctional systems;"],[1,"(5) provide notice of release of prisoners in accordance with subsections (b) and (c);"],[1,"(6) establish prerelease planning procedures that help prisoners—"],[2,"(A) apply for Federal and State benefits upon release (including Social Security benefits, and veterans' benefits);"],[2,"(B) obtain identification, including a social security card, driver's license or other official photo identification, and a birth certificate; and"],[2,"(C) secure such identification and benefits prior to release from a sentence to a term of imprisonment in a Federal prison or if the individual was not sentenced to a term of imprisonment in a Federal prison, prior to release from a sentence to a term of community confinement, subject to any limitations in law; and"],[1,"(7) establish reentry planning procedures that include providing Federal prisoners with information in the following areas:"],[2,"(A) Health and nutrition."],[2,"(B) Employment."],[2,"(C) Literacy and education."],[2,"(D) Personal finance and consumer skills."],[2,"(E) Community resources."],[2,"(F) Personal growth and development."],[2,"(G) Release requirements and procedures."],[0,"(b) Notice of Release of Prisoners.—(1) At least 5 days prior to the date on which a prisoner described in paragraph (3) is to be released on supervised release, or, in the case of a prisoner on supervised release, at least 5 days prior to the date on which the prisoner changes residence to a new jurisdiction, written notice of the release or change of residence shall be provided to the chief law enforcement officers of each State, tribal, and local jurisdiction in which the prisoner will reside. Notice prior to release shall be provided by the Director of the Bureau of Prisons. Notice concerning a change of residence following release shall be provided by the probation officer responsible for the supervision of the released prisoner, or in a manner specified by the Director of the Administrative Office of the United States Courts. The notice requirements under this subsection do not apply in relation to a prisoner being protected under chapter 224."],[0,"(2) A notice under paragraph (1) shall disclose—"],[1,"(A) the prisoner's name;"],[1,"(B) the prisoner's criminal history, including a description of the offense of which the prisoner was convicted; and"],[1,"(C) any restrictions on conduct or other conditions to the release of the prisoner that are imposed by law, the sentencing court, or the Bureau of Prisons or any other Federal agency."],[0,"(3) A prisoner is described in this paragraph if the prisoner was convicted of—"],[1,"(A) a drug trafficking crime, as that term is defined in section 924(c)(2); or"],[1,"(B) a crime of violence (as defined in section 924(c)(3))."],[0,"(c) Notice of Sex Offender Release.—(1) In the case of a person described in paragraph (3), or any other person in a category specified by the Attorney General, who is released from prison or sentenced to probation, notice shall be provided to—"],[1,"(A) the chief law enforcement officer of each State, tribal, and local jurisdiction in which the person will reside; and"],[1,"(B) a State, tribal, or local agency responsible for the receipt or maintenance of sex offender registration information in the State, tribal, or local jurisdiction in which the person will reside."],[0,"The notice requirements under this subsection do not apply in relation to a person being protected under chapter 224."],[0,"(2) Notice provided under paragraph (1) shall include the information described in subsection (b)(2), the place where the person will reside, and the information that the person shall register as required by the Sex Offender Registration and Notification Act. For a person who is released from the custody of the Bureau of Prisons whose expected place of residence following release is known to the Bureau of Prisons, notice shall be provided at least 5 days prior to release by the Director of the Bureau of Prisons. For a person who is sentenced to probation, notice shall be provided promptly by the probation officer responsible for the supervision of the person, or in a manner specified by the Director of the Administrative Office of the United States Courts. Notice concerning a subsequent change of residence by a person described in paragraph (3) during any period of probation, supervised release, or parole shall also be provided to the agencies and officers specified in paragraph (1) by the probation officer responsible for the supervision of the person, or in a manner specified by the Director of the Administrative Office of the United States Courts."],[0,"(3) The Director of the Bureau of Prisons shall inform a person who is released from prison and required to register under the Sex Offender Registration and Notification Act of the requirements of that Act as they apply to that person and the same information shall be provided to a person sentenced to probation by the probation officer responsible for supervision of that person."],[0,"[(4) Repealed. Pub. L. 109–248, title I, §141(h), July 27, 2006, 120 Stat. 604.]"],[0,"(5) The United States and its agencies, officers, and employees shall be immune from liability based on good faith conduct in carrying out this subsection and subsection (b)."],[0,"(d) Application of Section.—This section shall not apply to military or naval penal or correctional institutions or the persons confined therein."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/4042?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4042. Duties of Bureau of Prisons","tname":"Crimes and Criminal Procedure","by":{"2":"27"}},{"t":"usc","label":"28 U.S.C. § 4205","url":"https://www.law.cornell.edu/uscode/text/28/4205","subs":["(g)"],"by":{"2":"29, 30"}},{"t":"reg","label":"59 Fed. Reg. 1238","url":"https://www.govinfo.gov/link/fr/59/1238","by":{"2":"30"}},{"t":"case","label":"Chavez-Meza v. United States","cite":"585 U.S. 109","y":2018,"id":"2017/17-5639","sc":1,"sum":"The Court held that because the record in this case as a whole demonstrated that the judge had a reasoned basis for his decision, the judge’s explanation for reducing Adaucto Chavez-Meza’s sentence under 18 U.S.C. § 3582(c)(2) to the middle instead of the bottom of the amended Federal Guidelines range was adequate.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Continental Ore Co. v. Union Carbide & Carbon Corp.","cite":"370 U.S. 690","y":1962,"id":"1961/304","sc":1,"sum":"The judgment is vacated and the case is remanded for a new trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"CPSC v. GTE Sylvania, Inc.","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"sum":"Section 6 (b) (1) governs the disclosure of records by the Commission pursuant to a request under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Rainwater v. United States","cite":"356 U.S. 590","y":1958,"id":"1957/276","sc":1,"sum":"A claim against the Commodity Credit Corporation, a wholly owned government corporation operating within and as a part of the Department of Agriculture as an administrative device for the purpose of carrying but federal farm programs with public funds,,s a claim \"against the Government of the United States, or any department or officer thereof\" within the meaning of the civil provisions of the False Claims Act. Pp. …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Solem v. Helm","cite":"463 U.S. 277","y":1983,"id":"1982/82-492","sc":1,"sum":"Since all of Helm's prior offenses, including his current check-writing conviction, had been \"relatively minor\" and were not crimes against people, Justice Powell held that Helm had \"received the penultimate sentence (South Dakota did not have the death penalty) for relatively minor criminal conduct.\" Powell concluded that Helm was treated more harshly than the state's most violent criminals.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Truck Ins. Exch. v. Kaiser Gypsum Co.","cite":"602 U.S. 268","y":2024,"id":"2023/22-1079","sc":1,"sum":"An insurer with financial responsibility for bankruptcy claims is a “party in interest” under 11 U. S. C. §1109(b) that “may raise and may appear and be heard on any issue” in a Chapter 11 case.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"23"}},{"t":"case","label":"Turkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"22"}},{"t":"case","label":"United States v. Banks","cite":"428 F. Supp. 1088","y":1977,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp./428/1088/","op":1,"by":{"3":"20"}},{"t":"case","label":"United States v. Hymes","cite":"19 F.4th 928","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/19/928/","by":{"3":"8"}},{"t":"case","label":"United States v. Uriarte","cite":"975 F.3d 596","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/596/","by":{"3":"10"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"21"}},{"t":"usc","label":"18 U.S.C. § 3621","url":"https://www.law.cornell.edu/uscode/text/18/3621","subs":["(b)"],"by":{"3":"21"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","subs":["(g)"],"by":{"3":"7"}},{"t":"rule","label":"Fed. R. Crim. P. 35","url":"https://www.law.cornell.edu/rules/frcrmp/rule_35","subs":["(b)"],"by":{"3":"21","4":"18–19"}},{"t":"case","label":"King v. Burwell","cite":"576 U.S. 473","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"4":"28"}},{"t":"case","label":"Seven Cnty. Infrastructure Coal. v. Eagle Cnty.","cite":"145 S. Ct. 1497","y":2025,"id":"2024/23-975","sc":1,"sum":"The D. C. Circuit failed to afford the U. S. Surface Transportation Board the substantial deference required when reviewing agency action under the National Environmental Policy Act, and incorrectly interpreted NEPA to require the Board to consider in its environmental impact statement the environmental effects of temporally and geographically separate upstream and downstream projects unrelated to the Uinta Basin Railway.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"27"}},{"t":"case","label":"Torres v. Lynch","cite":"578 U.S. 452","y":2016,"id":"2015/14-1096","sc":1,"sum":"The Court determined that a state offense may constitute an aggravated felony for the purpose of the removal of a permanent resident when it includes all the elements of the federal statute with the exception of the interstate commerce element.","sumSrc":"Oyez","by":{"4":"24"}},{"t":"case","label":"United States v. Bryant","cite":"996 F.3d 1243","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/996/1243/","op":1,"by":{"4":"14"}},{"t":"case","label":"United States v. Ellenbogen","cite":"390 F.2d 537","y":1968,"court":"2d. Cir.","url":"https://www.courtlistener.com/c/F.2d/390/537/","by":{"4":"18"}},{"t":"case","label":"United States v. Gee","cite":"56 F.R.D. 377","y":1972,"court":"S.D. Tex.","url":"https://www.courtlistener.com/c/F.R.D./56/377/","by":{"4":"18"}},{"t":"case","label":"United States v. Jean","cite":"108 F.4th 275","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/108/275/","by":{"4":"17"}},{"t":"case","label":"Weinberger v. Hynson, Westcott & Dunning, Inc.","cite":"412 U.S. 609","y":1973,"id":"1972/72-394","sc":1,"sum":"The Federal Food, Drug, and Cosmetic Act of 1938, as amended in 1962, establishes a system of premarketing clearance for drugs and prohibits in § 505 (a)the introduction into commerce of any \"new drug\" unless a new drug application (NDA) filed with the Food and Drug Administration (FDA) was effective with respect to such drug. Under the Act procedures were established for filing \"new drug\" applications not only for …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"6"}},{"t":"case","label":"Whitfield v. United States","cite":"543 U.S. 209","y":2005,"id":"2004/03-1293","sc":1,"sum":"Justice Sandra Day O'Connor delivered the Court's unanimous ruling that because the federal money laundering law's text did not expressly make committing an overt act an element of the conspiracy offense, the government did not need to prove such an act.","sumSrc":"Oyez","by":{"4":"7"}},{"t":"reg","label":"28 C.F.R. § 572.40","url":"https://www.ecfr.gov/current/title-28/section-572.40","subs":["(a)"],"by":{"4":"19"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"4":"10"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"4":"10"}}]};